# Building

## The look

Show the person's site in two or three looks: for the pieces, the engine's looks at `/preview?look=`; for scenes of your own, the opening, one middle chapter and the ending, built in each. Let the person scroll them, ask which they choose, and stop for their answer before building on. An unanswered question in this turn is not a refusal to choose or permission to choose for them.

## What opens on a click, and the words

After the look choice, build what opens on a click (each project's page or window, the CV) and any remaining chapters of your own. For the opening and closing wording, show three versions of each whole beat, including the surrounding fixed text. Recommend one and leave room for their own wording. Stop for the choice, then use it word for word.

## The scene

This holds for the pieces with the person's data in them, and for a scene of your own. Compare the running scene with the storyboard at its settled beats. With the captions hidden, does each scene show what the storyboard says it shows, rather than only names for it? Revise the composition when the explanation lives only in the surrounding prose. Draw each diagram flat with the engine's pen, as `references/diagrams.md` says. Keep that accessible prose; it does not replace what the scene was meant to show.

Inspect the changes between beats in both scroll directions, including intermediate positions. When words in the scene change, correct any overlap that makes the old and new words unreadable together. A readable settled beat does not establish a readable transition. A scene that pops in or vanishes at a chapter's edge is not done: grow it out of the last.

Read every word in the scene at the size it is shown on a desktop, a phone and a short screen. Words too small to read there go to the caption.
"use client";
// A stitched story on a page: the 3D behind, the chapter's words, the
// chapter rail, the contact buttons and a project window. The words are
// also written out in full for anyone without the 3D.
import { useEffect, useMemo, useRef, useState, type CSSProperties } from "react";
import { titleOf, wordsFor, type ChapterKey } from "./chapters.ts";
import { chaptersFor, type Person, type Project } from "./person.ts";
import { formatMix, parseMix, type Mix } from "./mix.ts";
import { LOOKS, uiColours, type LookId, type Palette } from "./look.ts";
import { miniPicture, canvas as paintCanvas } from "./paint.ts";
import { smooth, type ScrollState } from "./scroll.ts";
import "./stitch.css";

type Handle = { dispose(): void; goTo(index: number, instant?: boolean): void };

/** The custom properties stitch.css colours the words, rail, caption and buttons with. */
function lookStyle(p: Palette): CSSProperties {
  const ui = uiColours(p);
  return { "--st-bg": p.bg, "--st-ink": ui.text, "--st-soft": ui.soft, "--st-muted": ui.muted, "--st-glass": ui.glass,
    "--st-line": ui.line, "--st-on-ink": ui.onText, "--st-amber": p.amber } as CSSProperties;
}

/**
 * `start` opens the story at that chapter when the page is at its top, as a link to one chapter's piece does.
 * `words` are the person's own words for any chapter; `cv` is where their CV is, and its button shows only with it.
 */
export function StitchedStory({ person, mix, showWords = true, start, look = "night", words: chosen, cv }: {
  person: Person; mix: Mix; showWords?: boolean; start?: ChapterKey; look?: LookId; words?: Partial<Record<ChapterKey, string>>; cv?: string;
}) {
  const palette = LOOKS[look];
  const keys = useMemo(() => chaptersFor(person), [person]);
  const words = useMemo(() => wordsFor(person, keys, chosen), [person, keys, chosen]);
  const mixText = formatMix(mix);
  const chosenText = JSON.stringify(chosen ?? {});
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const spacerRef = useRef<HTMLDivElement>(null);
  const capRef = useRef<HTMLDivElement>(null);
  const hintRef = useRef<HTMLDivElement>(null);
  const ctaRef = useRef<HTMLDivElement>(null);
  const handle = useRef<Handle | null>(null);
  const nearRef = useRef(0);
  const [near, setNear] = useState(0);
  const [scene, setScene] = useState<"wait" | "on" | "off">("wait");
  const [project, setProject] = useState<Project | null>(null);

  useEffect(() => {
    const canvas = canvasRef.current, spacer = spacerRef.current;
    if (!canvas || !spacer) return;
    let alive = true;
    const last = keys.length - 1;
    const onState = (st: ScrollState) => {
      const n = st.t < 0.5 ? st.from : st.to;
      if (n !== nearRef.current) { nearRef.current = n; setNear(n); }
      const fade = st.to === st.from ? 1 : 1 - smooth(0.05, 0.35, st.raw) + smooth(0.65, 0.95, st.raw);
      if (capRef.current) capRef.current.style.opacity = fade.toFixed(3);
      if (hintRef.current) hintRef.current.style.opacity = st.s < 0.15 ? "1" : "0";
      const cta = st.from === last ? 1 : st.to === last ? smooth(0.7, 1, st.raw) : 0;
      if (ctaRef.current) { ctaRef.current.style.opacity = cta.toFixed(3); ctaRef.current.style.pointerEvents = cta > 0.5 ? "auto" : "none"; }
    };
    import("./stage.ts")
      .then(({ mountStitch }) => mountStitch(canvas, { person, mix: parseMix(mixText)!, palette: LOOKS[look], words: JSON.parse(chosenText), spacer, onState, onProject: setProject }))
      .then((h) => {
        if (!alive) { h.dispose(); return; }
        handle.current = h;
        setScene("on");
        const at = start ? keys.indexOf(start) : -1;
        if (at > 0 && window.scrollY < 2) h.goTo(at, true);
      })
      .catch((e) => { console.error(e); if (alive) setScene("off"); });
    return () => { alive = false; handle.current?.dispose(); handle.current = null; };
  }, [person, mixText, keys, start, look, chosenText]);

  useEffect(() => {
    if (!project) return;
    const close = (e: KeyboardEvent) => { if (e.key === "Escape") setProject(null); };
    window.addEventListener("keydown", close);
    return () => window.removeEventListener("keydown", close);
  }, [project]);

  const key = keys[near];
  return (
    <div className={`stitch${showWords ? "" : " nowords"}`} data-scene={scene} style={lookStyle(palette)}>
      <canvas ref={canvasRef} className="gl" aria-hidden="true" />
      <div ref={spacerRef} className="spacer" />
      <div className="ui">
        <nav className="rail" aria-label="Chapters">
          {keys.map((k, i) => (
            <button key={k} type="button" className={i === near ? "on" : ""} onClick={() => handle.current?.goTo(i)}>
              <i /><span>{titleOf(k)}</span>
            </button>
          ))}
        </nav>
        <div ref={capRef} className={`cap${mix[key] === "book" ? " inbook" : ""}`} aria-live="polite">
          <div className="num">{String(near + 1).padStart(2, "0")}</div>
          <h2>{titleOf(key)}</h2>
          <p>{words[key]}</p>
        </div>
        <div ref={hintRef} className="hint">Scroll</div>
      </div>
      <div ref={ctaRef} className="cta">
        <a href={`mailto:${person.contact.email}`}>Email {person.first}</a>
        {cv && <a href={cv}>CV</a>}
      </div>
      <Chapters person={person} keys={keys} words={words} cv={cv} />
      <Expected person={person} words={words} cv={cv} />
      {project && <ProjectWindow project={project} palette={palette} onClose={() => setProject(null)} />}
    </div>
  );
}

/** Every chapter's words in order, shown when there is no 3D and read by screen readers. */
function Chapters({ person, keys, words, cv }: { person: Person; keys: ChapterKey[]; words: Partial<Record<ChapterKey, string>>; cv?: string }) {
  return (
    <section className="text" aria-label={`${person.name}, in words`}>
      <h1>{person.name}</h1>
      {keys.map((k) => (
        <article key={k}>
          <h2>{titleOf(k)}</h2>
          <p>{words[k]}</p>
          {k === "made" && <ul>{person.projects.map((p) => <li key={p.title}><b>{p.page ? <a href={p.page}>{p.title}</a> : p.title}</b>. {p.line}{p.more && <> {p.more}</>}</li>)}</ul>}
          {k === "say" && <ul>{person.quotes.map((q) => <li key={q.who}>&ldquo;{q.text}&rdquo; {q.who}, {q.from}</li>)}</ul>}
          {k === "contact" && <p><a href={`mailto:${person.contact.email}`}>{person.contact.email}</a>{cv && <>. <a href={cv}>CV</a></>}</p>}
        </article>
      ))}
    </section>
  );
}

/** What the page must show without its 3D, as JSON for scripts/site-check.mjs to look for. */
function Expected({ person, words, cv }: { person: Person; words: Partial<Record<ChapterKey, string>>; cv?: string }) {
  const wanted = {
    name: person.name,
    words: Object.values(words),
    projects: person.projects.map(({ title, line, more, page }) => ({ title, line, more, page })),
    cv,
  };
  return <script type="application/json" data-stitch-expect dangerouslySetInnerHTML={{ __html: JSON.stringify(wanted).replace(/</g, "\\u003c") }} />;
}

function ProjectWindow({ project, palette, onClose }: { project: Project; palette: Palette; onClose: () => void }) {
  const pic = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const el = pic.current;
    if (!el) return;
    const c = paintCanvas(800, 420, (ctx, w, h) => miniPicture(ctx, palette, project.kind, 0, 0, w, h, project.title.length));
    el.replaceChildren(c);
  }, [project, palette]);
  return (
    <div className="modal open" role="dialog" aria-modal="true" aria-label={project.title} onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="sheet">
        <button type="button" data-close aria-label="Close" onClick={onClose}>&times;</button>
        <div className="pic" ref={pic} />
        <div className="body">
          <div className="eyebrow">{project.place}, {project.year}</div>
          <h3>{project.title}</h3>
          <p>{project.line}</p>
          {project.more && <p>{project.more}</p>}
          {project.page && <p><a className="more" href={project.page}>More about {project.title}</a></p>}
          <div className="tags">{project.tags.map((t) => <span key={t}>{t}</span>)}</div>
        </div>
      </div>
    </div>
  );
}

@import "tailwindcss";
@import "../components/story/story.css";
:root { font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }
* { box-sizing: border-box; }
body { margin: 0; }
a { color: inherit; }
button, select { font: inherit; }
import { StitchedStory } from "@/stitch/react";
import { person } from "@/content/person";
import { mix } from "@/content/mix";
import { site } from "@/content/site";

// The person's site: their story stitched from the worlds in content/mix.ts,
// in the look, words and CV of content/site.ts.
export default function Home() {
  return <main><StitchedStory person={person} mix={mix} look={site.look} words={site.words} cv={site.cv} /></main>;
}
import type { Metadata } from "next";
import { person } from "@/content/person";
import { site } from "@/content/site";
import "./globals.css";

// Every page is titled with the person's name and described by what they do,
// unless it gives a title of its own (a project's page, the CV).
export const metadata: Metadata = { title: person.name, description: `${person.role}. ${person.line}` };
export default function RootLayout({ children }: { children: React.ReactNode }) {
  return <html lang={site.lang ?? "en"}><body>{children}</body></html>;
}
/* A stitched story. Everything sits under .stitch, so a page can hold other things. */
.stitch {
  /* Night's colours; StitchedStory sets the look's own (look.ts). */
  --st-bg: #0f1318; --st-ink: #ece6d9; --st-soft: #c9cfd5; --st-muted: #9aa4ae; --st-amber: #e9a23b;
  --st-line: rgba(236, 230, 217, 0.14); --st-glass: rgba(12, 16, 21, 0.72); --st-on-ink: #11161c;
  --st-serif: Georgia, "Times New Roman", serif; --st-sans: system-ui, sans-serif;
  position: relative; color: var(--st-ink); background: var(--st-bg); font-family: var(--st-sans);
  -webkit-font-smoothing: antialiased; min-height: 100vh;
}
.stitch a { color: inherit; }
.stitch .gl { position: fixed; inset: 0; width: 100%; height: 100%; display: block; z-index: 0; }
.stitch .spacer { position: relative; z-index: -1; }

.stitch .ui { position: fixed; inset: 0; pointer-events: none; z-index: 2; }
.stitch .rail { position: absolute; right: 18px; top: 50%; transform: translateY(-50%); display: flex; flex-direction: column; gap: 6px; }
.stitch .rail button { pointer-events: auto; display: flex; align-items: center; justify-content: flex-end; gap: 10px; background: none; border: 0;
  color: var(--st-muted); font: 500 13px var(--st-sans); cursor: pointer; padding: 3px 0; flex-direction: row-reverse; }
/* A halo in the caption glass's colour keeps the rail and hint readable over any world, such as the book's dark desk in a light look. */
.stitch .rail button, .stitch .hint { text-shadow: 0 0 3px var(--st-glass), 0 0 8px var(--st-glass), 0 0 14px var(--st-glass); }
.stitch .rail i { width: 7px; height: 7px; border-radius: 50%; background: currentColor; opacity: 0.5; box-shadow: 0 0 0 2px var(--st-glass); }
.stitch .rail button.on { color: var(--st-ink); }
.stitch .rail button.on i { background: var(--st-amber); opacity: 1; transform: scale(1.4); }
.stitch .cap { position: absolute; left: 24px; bottom: 28px; max-width: 430px; padding: 18px 20px; border-radius: 14px;
  background: var(--st-glass); backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px); border: 1px solid var(--st-line); }
.stitch .cap .num { color: var(--st-amber); font: 600 12px var(--st-sans); letter-spacing: 0.12em; }
.stitch .cap h2 { font-family: var(--st-serif); font-weight: 600; font-size: 26px; margin: 4px 0 6px; }
.stitch .cap p { margin: 0; color: var(--st-soft); line-height: 1.5; font-size: 15px; }
.stitch .hint { position: absolute; bottom: 26px; left: 50%; transform: translateX(-50%); color: var(--st-muted); font-size: 13px; letter-spacing: 0.1em;
  text-transform: uppercase; transition: opacity 0.4s; }
.stitch.nowords .cap, .stitch.nowords .rail span, .stitch.nowords .hint { display: none; }
/* In the book the left page carries the chapter's words. */
.stitch .cap.inbook { display: none; }

.stitch .cta { position: fixed; z-index: 3; left: 50%; bottom: 34px; transform: translateX(-50%); display: flex; gap: 10px; opacity: 0; pointer-events: none; }
.stitch .cta a { border-radius: 999px; padding: 12px 20px; font: 600 15px var(--st-sans); text-decoration: none; background: var(--st-amber); color: #11161c; white-space: nowrap; }
.stitch .cta a + a { background: var(--st-ink); color: var(--st-on-ink); }

.stitch .modal { position: fixed; inset: 0; z-index: 10; background: rgba(5, 7, 10, 0.6); display: grid; place-items: center; padding: 16px; }
.stitch .modal .sheet { position: relative; width: min(620px, 100%); max-height: calc(100vh - 32px); overflow: auto; background: #f2ede2; color: #1c222a; border-radius: 16px; }
.stitch .modal .pic canvas { width: 100%; display: block; }
.stitch .modal .body { padding: 20px 24px 26px; }
.stitch .modal .eyebrow { color: #b47718; font: 600 12px var(--st-sans); letter-spacing: 0.12em; text-transform: uppercase; }
.stitch .modal h3 { font-family: var(--st-serif); font-size: 30px; margin: 6px 0 8px; }
.stitch .modal p { margin: 0 0 10px; line-height: 1.55; }
.stitch .modal .more { color: #6d7782; font-size: 14px; }
.stitch .modal .tags span { display: inline-block; border: 1px solid #c9c1b0; border-radius: 999px; padding: 4px 10px; font-size: 13px; margin: 0 6px 6px 0; }
.stitch .modal [data-close] { position: absolute; top: 10px; right: 12px; border: 0; background: rgba(255, 255, 255, 0.8); border-radius: 50%;
  width: 34px; height: 34px; font-size: 22px; line-height: 1; cursor: pointer; color: #1c222a; }

/* The words in full: on the page without the 3D, for screen readers only with it. */
.stitch .text { position: relative; z-index: 1; max-width: 680px; margin: 0 auto; padding: 48px 20px 80px; line-height: 1.55; }
.stitch .text h1 { font-family: var(--st-serif); font-size: 40px; margin: 0 0 24px; }
.stitch .text h2 { font-family: var(--st-serif); font-size: 24px; margin: 28px 0 6px; }
.stitch[data-scene="on"] .text, .stitch[data-scene="wait"] .text {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}
.stitch[data-scene="off"] .gl, .stitch[data-scene="off"] .ui, .stitch[data-scene="off"] .cta, .stitch[data-scene="off"] .spacer { display: none; }

@media (max-width: 720px) {
  .stitch .rail span { display: none; }
  .stitch .rail { right: 8px; }
  .stitch .cap { left: 12px; right: 12px; bottom: 14px; max-width: none; padding: 12px 14px; }
  .stitch .cap h2 { font-size: 20px; margin: 2px 0 4px; }
  .stitch .cap p { font-size: 14px; line-height: 1.4; }
  .stitch .cta { bottom: 22px; }
}
